    private const PREFIX='_verbum_structure_index_';private const SUBSTEPS='_verbum_structure_substeps';private const TYPES=['part','chapter','subchapter','element_initial','element_final'];
    /** @return array<string,mixed> */
    public function data(int$id):array{$sub=get_post_meta($id,self::SUBSTEPS,true);$sub=is_array($sub)?$sub:[];$raw=get_post_meta($id,self::PREFIX.'items',true);$items=is_array($raw)?$this->normalize($raw):$this->architectureSeeds($id);$chapters=$this->chapters($id);$preview=$this->preview($items,$chapters);$suggestions=get_post_meta($id,self::PREFIX.'review_suggestions',true);$suggestions=is_array($suggestions)?$suggestions:[];return['substep'=>'provisional-index','order'=>4,'total'=>4,'items'=>$items,'expanded'=>(array)get_post_meta($id,self::PREFIX.'expanded',true),'reviewSuggestions'=>$suggestions,'revision'=>max(0,(int)get_post_meta($id,self::PREFIX.'revision',true)),'updatedAt'=>(string)get_post_meta($id,self::PREFIX.'updated_at',true),'completed'=>in_array('provisional-index',$sub,true),'completedSubsteps'=>array_values($sub),'prerequisites'=>['direction'=>in_array('direction',$sub,true),'architecture'=>in_array('architecture',$sub,true),'elements'=>in_array('elements',$sub,true)],'activeElements'=>count(array_filter((array)get_post_meta($id,'_verbum_structure_elements_items',true),static fn($x):bool=>is_array($x)&&!empty($x['active']))),'realChapters'=>$chapters,'preview'=>$preview,'legacy'=>$this->legacy($id)];}
    /** @param array<string,mixed>$fields @return array<string,mixed> */ public function save(int$id,array$fields):array{$rev=max(0,(int)get_post_meta($id,self::PREFIX.'revision',true));$base=array_key_exists('base_revision',$fields)?max(0,(int)$fields['base_revision']):$rev;if($base!==$rev)throw new ValidationError('Este índice foi atualizado em outra sessão. Recarregue antes de salvar novamente.');$before=(array)get_post_meta($id,self::PREFIX.'items',true);$items=$this->normalize((array)($fields['items']??[]));$this->assertHierarchy($items);if($before!==$items)$this->history($id,$rev,$before,'save');update_post_meta($id,self::PREFIX.'items',$items);update_post_meta($id,self::PREFIX.'expanded',array_values(array_filter(array_map('sanitize_key',(array)($fields['expanded']??[])))));if(array_key_exists('review_suggestions',$fields))update_post_meta($id,self::PREFIX.'review_suggestions',$this->reviewSuggestions((array)$fields['review_suggestions']));update_post_meta($id,self::PREFIX.'revision',$rev+1);update_post_meta($id,self::PREFIX.'updated_at',gmdate('c'));$this->markComparisonNeeded($id);$this->touch($id);return$this->data($id);}
    /** @return array<string,mixed> */ public function complete(int$id):array{$d=$this->data($id);foreach($d['prerequisites']as$k=>$ok)if(!$ok)throw new ValidationError('Conclua as três subetapas anteriores antes de concluir a Estrutura.');$items=(array)$d['items'];$this->assertHierarchy($items);if(count(array_filter($items,static fn($x):bool=>($x['type']??'')==='part'))<1)throw new ValidationError('Adicione pelo menos uma Parte ao Índice Provisório.');if(count(array_filter($items,static fn($x):bool=>($x['type']??'')==='chapter'))<1)throw new ValidationError('Adicione pelo menos um Capítulo provisório.');$pending=array_filter((array)$d['reviewSuggestions'],static fn($x):bool=>($x['status']??'pending')==='pending');if($pending!==[])throw new ValidationError('Aceite ou rejeite todas as sugestões da revisão antes de concluir.');$sub=(array)$d['completedSubsteps'];if(!in_array('provisional-index',$sub,true))$sub[]='provisional-index';update_post_meta($id,self::SUBSTEPS,array_values(array_unique($sub)));$completed=get_post_meta($id,'_verbum_completed_stages',true);$completed=is_array($completed)?$completed:[];if(!in_array('planning',$completed,true))$completed[]='planning';update_post_meta($id,'_verbum_completed_stages',array_values(array_unique($completed)));update_post_meta($id,'_verbum_stage','development');update_post_meta($id,self::PREFIX.'completed_at',gmdate('c'));update_post_meta($id,self::PREFIX.'comparison_needed',1);$this->touch($id);return$this->data($id);}
    /** @param array<int,mixed>$items @return array<int,array<string,mixed>> */ private function normalize(array$items):array{$out=[];$seen=[];foreach($items as$i=>$x){if(!is_array($x))continue;$type=sanitize_key((string)($x['type']??'chapter'));if(!in_array($type,self::TYPES,true))$type='chapter';$id=sanitize_key((string)($x['id']??''));if($id===''||strpos($id,'new-')===0)$id='index-'.substr(md5(wp_json_encode($x).'|'.$i.'|'.microtime(true)),0,12);if(isset($seen[$id]))$id.='-'.($i+1);$seen[$id]=1;$origin=sanitize_key((string)($x['origin']??'manual'));if(!in_array($origin,['imported','ai','manual','existing'],true))$origin='manual';$state=sanitize_key((string)($x['state']??'analysis'));if(!in_array($state,['ready','analysis','pending','approved'],true))$state='analysis';$out[]=['id'=>$id,'type'=>$type,'title'=>trim(sanitize_text_field((string)($x['title']??''))),'parentId'=>sanitize_key((string)($x['parentId']??'')),'origin'=>$origin,'state'=>$state,'purpose'=>sanitize_textarea_field((string)($x['purpose']??'')),'thesisContribution'=>sanitize_textarea_field((string)($x['thesisContribution']??'')),'expectedResult'=>sanitize_textarea_field((string)($x['expectedResult']??'')),'movementId'=>sanitize_key((string)($x['movementId']??'')),'architecturePartId'=>sanitize_key((string)($x['architecturePartId']??'')),'elementId'=>sanitize_key((string)($x['elementId']??'')),'realChapterId'=>preg_replace('/\D+/','',(string)($x['realChapterId']??''))?:'','order'=>count($out)+1];}return$out;}
    /** @param array<int,array<string,mixed>>$items */ private function assertHierarchy(array$items):void{$by=[];foreach($items as$x)$by[$x['id']]=$x;foreach($items as$x){if(trim((string)$x['title'])==='')throw new ValidationError('Todos os itens do índice precisam de título.');$p=(string)$x['parentId'];if($x['type']==='part'&&$p!=='')throw new ValidationError('Uma Parte não pode ser filha de outro item.');if($x['type']==='chapter'&&($p===''||!isset($by[$p])||$by[$p]['type']!=='part'))throw new ValidationError('Todo Capítulo provisório precisa pertencer a uma Parte.');if($x['type']==='subchapter'&&($p===''||!isset($by[$p])||$by[$p]['type']!=='chapter'))throw new ValidationError('Todo Subcapítulo precisa pertencer a um Capítulo.');if(in_array($x['type'],['element_initial','element_final'],true)&&$p!=='')throw new ValidationError('Elementos editoriais não podem ficar dentro de Partes ou Capítulos.');$cursor=$p;$seen=[$x['id']];while($cursor!==''){if(in_array($cursor,$seen,true))throw new ValidationError('A hierarquia não pode formar ciclos.');$seen[]=$cursor;$cursor=isset($by[$cursor])?(string)$by[$cursor]['parentId']:'';}}}
    /** @return array<int,array<string,mixed>> */ private function architectureSeeds(int$id):array{$parts=get_post_meta($id,'_verbum_structure_architecture_parts',true);$parts=is_array($parts)?$parts:[];$out=[];foreach($parts as$i=>$p)if(is_array($p))$out[]=['id'=>'part-'.sanitize_key((string)($p['id']??($i+1))),'type'=>'part','title'=>(string)($p['title']??''),'parentId'=>'','origin'=>(string)($p['origin']??'manual'),'state'=>(string)($p['state']??'analysis'),'purpose'=>'','thesisContribution'=>'','expectedResult'=>'','movementId'=>(string)($p['movementId']??''),'architecturePartId'=>(string)($p['id']??''),'elementId'=>'','realChapterId'=>'','order'=>count($out)+1];return$this->normalize($out);}
    /** @return array<int,array<string,mixed>> */ private function chapters(int$id):array{$q=new \WP_Query(['post_type'=>LibraryPostTypes::CHAPTER,'post_status'=>'publish','posts_per_page'=>-1,'meta_key'=>'_verbum_book_id','meta_value'=>$id,'no_found_rows'=>true]);$o=[];foreach((array)$q->posts as$p){$cid=$p instanceof \WP_Post?(int)$p->ID:(int)$p;if($cid>0)$o[]=['id'=>(string)$cid,'itemId'=>(string)get_post_meta($cid,'_verbum_planning_item_id',true),'title'=>get_the_title($cid),'order'=>max(1,(int)get_post_meta($cid,'_verbum_chapter_order',true))];}usort($o,static fn($a,$b):int=>$a['order']<=>$b['order']);return$o;}
    /** @param array<int,array<string,mixed>>$items @param array<int,array<string,mixed>>$chapters @return array<string,mixed> */ private function preview(array$items,array$chapters):array{$linked=[];$new=0;foreach($items as$x)if($x['type']==='chapter'){if($x['realChapterId']!=='')$linked[]=$x['realChapterId'];else$new++;}$removed=array_values(array_filter($chapters,static fn($c):bool=>!in_array((string)$c['id'],$linked,true)));return['existing'=>count($linked),'new'=>$new,'possibleRemovals'=>count($removed),'possibleRemovalItems'=>$removed,'total'=>count($linked)+$new];}
    /** @return array<string,mixed> */ private function legacy(int$id):array{return['items'=>(array)get_post_meta($id,'_verbum_planning_structure_items',true),'generalStructure'=>(string)get_post_meta($id,'_verbum_planning_general_structure',true),'unmigrated'=>(array)get_post_meta($id,self::PREFIX.'unmigrated',true)];}/** @param array<int,mixed>$x @return array<int,array<string,mixed>> */ private function reviewSuggestions(array$x):array{$o=[];foreach($x as$v)if(is_array($v))$o[]=['id'=>sanitize_key((string)($v['id']??('review-'.count($o)))),'itemId'=>sanitize_key((string)($v['itemId']??'')),'observation'=>sanitize_textarea_field((string)($v['observation']??'')),'impact'=>sanitize_textarea_field((string)($v['impact']??'')),'status'=>in_array(($v['status']??''),['pending','accepted','rejected'],true)?(string)$v['status']:'pending'];return$o;}private function markComparisonNeeded(int$id):void{update_post_meta($id,self::PREFIX.'comparison_needed',1);$completed=get_post_meta($id,'_verbum_completed_stages',true);if(is_array($completed)&&in_array('planning',$completed,true))update_post_meta($id,'_verbum_completed_stages',array_values(array_diff($completed,['planning'])));}private function history(int$id,int$rev,array$before,string$action):void{$h=get_post_meta($id,self::PREFIX.'history',true);$h=is_array($h)?$h:[];$h[]=['revision'=>$rev,'action'=>$action,'items'=>$before,'savedAt'=>gmdate('c'),'userId'=>get_current_user_id()];update_post_meta($id,self::PREFIX.'history',array_slice($h,-30));}private function touch(int$id):void{$p=get_post($id);if($p instanceof \WP_Post)wp_update_post(['ID'=>$id,'post_content'=>$p->post_content]);}
}
